// Lista de entities_id tratados como VIP (edite aqui — sem precisar reimportar o
// workflow inteiro). Ver Apps/workflows/sla-triagem-omnicanal.md.
const VIP_ENTITIES = [];

const alert = $input.first().json.body ?? $input.first().json;
const entitiesId = Number(alert.entities_id) || 0;
const isVip = entitiesId > 0 && VIP_ENTITIES.includes(entitiesId);

return [
  {
    json: {
      ...alert,
      is_vip: isVip,
    },
  },
];

// Monta o MessageCard do Teams no mesmo formato usado pelo canal direto do
// dashglpi (Apps/dashglpi/inc/messaging/teams_channel.php) — mesmas cores/emoji
// por nível, para o time ver um único estilo de card independente do caminho.
const a = $input.first().json;

const themeColor = a.level === 'warn' ? 'FFB020' : (a.level === 'info' ? '2A9D8F' : 'D2314B');
const emoji = a.level === 'warn' ? '\u26A0\uFE0F' : (a.level === 'info' ? '\uD83D\uDCCC' : '\uD83D\uDEA8');
const levelLabel = a.level === 'warn' ? 'Aten\u00e7\u00e3o de SLA' : (a.level === 'info' ? 'Novo Evento' : 'SLA estourado');

const facts = [
  { name: 'Chamado', value: '#' + (a.ticket_id ?? '0') },
  { name: 'Entidade', value: a.entity_name || '\u2014' },
  { name: 'Categoria', value: a.category || '\u2014' },
];
if (a.created_at_formatted) {
  facts.push({ name: a.event_at_label || 'Ocorrido em', value: a.created_at_formatted });
}
facts.push({
  name: (a.threshold > 0) ? 'Sem a\u00e7\u00e3o h\u00e1' : 'Detectado h\u00e1',
  value: (a.minutes_overdue ?? 0) + ' min' + (a.threshold > 0 ? (' (limite: ' + a.threshold + ' min)') : ''),
});
if (a.note) {
  facts.push({ name: 'Detalhe', value: a.note });
}

const actions = [];
if (a.url) {
  actions.push({ '@type': 'OpenUri', name: 'Visualizar Chamado (GLPI)', targets: [{ os: 'default', uri: a.url }] });
}
if (a.dashboard_url) {
  actions.push({ '@type': 'OpenUri', name: 'Abrir no DashGLPI', targets: [{ os: 'default', uri: a.dashboard_url }] });
}

const card = {
  '@type': 'MessageCard',
  '@context': 'https://schema.org/extensions',
  themeColor,
  title: emoji + ' ' + levelLabel,
  summary: levelLabel + ' - Chamado #' + (a.ticket_id ?? '0'),
  sections: [
    {
      activityTitle: '**' + (a.title || ('Chamado #' + (a.ticket_id ?? '0'))) + '**',
      activitySubtitle: 'Fealq \u00b7 n8n (SLA Triagem Omnicanal)',
      facts,
      markdown: true,
    },
  ],
};
if (actions.length) {
  card.potentialAction = actions;
}

return [{ json: { ...a, teams_card: card } }];

const a = $input.first().json;
const lines = [
  '\uD83D\uDEA8 Chamado VIP: #' + (a.ticket_id ?? '0'),
  a.title || '',
  'Entidade: ' + (a.entity_name || '\u2014'),
  'Categoria: ' + (a.category || '\u2014'),
];
if (a.created_at_formatted) {
  lines.push((a.event_at_label || 'Ocorrido em') + ': ' + a.created_at_formatted);
}
lines.push('Sem a\u00e7\u00e3o h\u00e1: ' + (a.minutes_overdue ?? 0) + ' min');
if (a.url) {
  lines.push('');
  lines.push('GLPI: ' + a.url);
}

return [{ json: { ...a, whatsapp_text: lines.filter((l) => l !== undefined).join('\n') } }];
